-- Rôle des semaines après la refonte de la charge (9 langues). Rejouable.
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "4 semaines, 3 à 4 séances de 45 à 75 minutes. Sprints assis de 15 à 20 s (170-180 % FTP), relances d''une minute (115-125 % FTP) et séries de 30/30 (130 % FTP), toujours en TT, plus deux séances d''endurance TT par semaine. Pour les CLM et triathlons où il faut relancer après un virage, une bosse ou un dépassement sans se relever. Au plus 2 séances intenses par semaine, chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "4 weeks, 3 to 4 sessions of 45 to 75 minutes. Seated 15 to 20 s sprints (170-180% FTP), one-minute surges (115-125% FTP) and 30/30 sets (130% FTP), always in TT, plus two TT endurance sessions a week. For TTs and triathlons where you must surge after a corner, a rise or a pass without sitting up. At most 2 hard sessions a week, each with a dedicated warm-up; space them at least 48 h apart.", "es": "4 semanas, 3 a 4 sesiones de 45 a 75 minutos. Sprints sentado de 15 a 20 s (170-180 % FTP), cambios de ritmo de un minuto (115-125 % FTP) y series 30/30 (130 % FTP), siempre en TT, más dos sesiones de resistencia TT por semana. Para CRI y triatlones donde hay que acelerar tras una curva, un repecho o un adelantamiento sin incorporarse. Como máximo 2 sesiones intensas por semana, cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "4 settimane, da 3 a 4 sessioni da 45 a 75 minuti. Sprint seduti da 15 a 20 s (170-180 % FTP), rilanci di un minuto (115-125 % FTP) e serie 30/30 (130 % FTP), sempre in TT, più due sessioni di resistenza TT a settimana. Per crono e triathlon dove bisogna rilanciare dopo una curva, uno strappo o un sorpasso senza rialzarsi. Al massimo 2 sessioni intense a settimana, ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "4 Wochen, 3 bis 4 Einheiten von 45 bis 75 Minuten. Sitzende Sprints von 15 bis 20 s (170-180 % FTP), einminütige Antritte (115-125 % FTP) und 30/30-Serien (130 % FTP), immer in TT, dazu zwei TT-Ausdauereinheiten pro Woche. Für Zeitfahren und Triathlons, in denen man nach Kurven, Wellen oder Überholmanövern antreten muss, ohne sich aufzurichten. Höchstens 2 intensive Einheiten pro Woche, jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "4 weken, 3 tot 4 sessies van 45 tot 75 minuten. Zittende sprints van 15 tot 20 s (170-180 % FTP), versnellingen van een minuut (115-125 % FTP) en 30/30-series (130 % FTP), altijd in TT, plus twee TT-duursessies per week. Voor tijdritten en triatlons waar je na een bocht, heuveltje of inhaalactie moet versnellen zonder overeind te komen. Maximaal 2 intensieve sessies per week, elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "4 semanas, 3 a 4 sessões de 45 a 75 minutos. Sprints sentado de 15 a 20 s (170-180 % FTP), retomadas de um minuto (115-125 % FTP) e séries 30/30 (130 % FTP), sempre em TT, mais duas sessões de resistência TT por semana. Para contrarrelógios e triatlos em que é preciso retomar após uma curva, uma subida ou uma ultrapassagem sem levantar. No máximo 2 sessões intensas por semana, cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "4週間、45〜75分のセッションを週3〜4回。15〜20秒のシッティングスプリント（170〜180 % FTP）、1分の加速（115〜125 % FTP）、30/30（130 % FTP）を常にTTで。加えて週2回のTT持久セッション。カーブや登り、追い越しの後に起き上がらずに加速が必要なTTやトライアスロン向け。 強度の高いセッションは週2回まで、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "4 hafta, haftada 45-75 dakikalık 3-4 seans. Oturarak 15-20 sn sprintler (%170-180 FTP), bir dakikalık ataklar (%115-125 FTP) ve 30/30 setleri (%130 FTP), hep TT''de; ayrıca haftada iki TT dayanıklılık seansı. Viraj, yokuş ya da sollama sonrası doğrulmadan atak yapmak gereken zamana karşı ve triatlonlar için. Haftada en fazla 2 yoğun seans, her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'sprint_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "4 semaines, 3 à 4 séances de 50 à 75 minutes, tous les efforts en TT : sweet spot (88-92 % FTP) de 10 à 20 minutes, seuil (95-100 % FTP) de 6 à 12 minutes, sur-sous (108/95 % FTP) et puissance critique (110-115 % FTP) sur 3 à 4 minutes. La puissance que tu développes est celle que tu sauras tenir en course, dans ta position. Au plus 2 séances intenses par semaine, chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "4 weeks, 3 to 4 sessions of 50 to 75 minutes, all efforts in TT: sweet spot (88-92% FTP) for 10 to 20 minutes, threshold (95-100% FTP) for 6 to 12 minutes, over-unders (108/95% FTP) and critical power (110-115% FTP) over 3 to 4 minutes. The power you build is the power you''ll hold in a race, in your position. At most 2 hard sessions a week, each with a dedicated warm-up; space them at least 48 h apart.", "es": "4 semanas, 3 a 4 sesiones de 50 a 75 minutos, todos los esfuerzos en TT: sweet spot (88-92 % FTP) de 10 a 20 minutos, umbral (95-100 % FTP) de 6 a 12 minutos, sobre-bajo (108/95 % FTP) y potencia crítica (110-115 % FTP) de 3 a 4 minutos. La potencia que desarrollas es la que sabrás mantener en carrera, en tu posición. Como máximo 2 sesiones intensas por semana, cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "4 settimane, da 3 a 4 sessioni da 50 a 75 minuti, tutti gli sforzi in TT: sweet spot (88-92 % FTP) da 10 a 20 minuti, soglia (95-100 % FTP) da 6 a 12 minuti, sopra-sotto (108/95 % FTP) e potenza critica (110-115 % FTP) su 3-4 minuti. La potenza che sviluppi è quella che saprai tenere in gara, nella tua posizione. Al massimo 2 sessioni intense a settimana, ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "4 Wochen, 3 bis 4 Einheiten von 50 bis 75 Minuten, alle Belastungen in TT: Sweet Spot (88-92 % FTP) über 10 bis 20 Minuten, Schwelle (95-100 % FTP) über 6 bis 12 Minuten, Over-Under (108/95 % FTP) und kritische Leistung (110-115 % FTP) über 3 bis 4 Minuten. Die Leistung, die du aufbaust, kannst du im Rennen in deiner Position halten. Höchstens 2 intensive Einheiten pro Woche, jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "4 weken, 3 tot 4 sessies van 50 tot 75 minuten, alle inspanningen in TT: sweet spot (88-92 % FTP) van 10 tot 20 minuten, drempel (95-100 % FTP) van 6 tot 12 minuten, over-unders (108/95 % FTP) en kritisch vermogen (110-115 % FTP) over 3 tot 4 minuten. Het vermogen dat je opbouwt, kun je in wedstrijd vasthouden, in je houding. Maximaal 2 intensieve sessies per week, elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "4 semanas, 3 a 4 sessões de 50 a 75 minutos, todos os esforços em TT: sweet spot (88-92 % FTP) de 10 a 20 minutos, limiar (95-100 % FTP) de 6 a 12 minutos, acima-abaixo (108/95 % FTP) e potência crítica (110-115 % FTP) em 3 a 4 minutos. A potência que você desenvolve é a que saberá manter em prova, na sua posição. No máximo 2 sessões intensas por semana, cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "4週間、50〜75分のセッションを週3〜4回、全ての努力をTTで：スイートスポット（88〜92 % FTP）10〜20分、閾値（95〜100 % FTP）6〜12分、オーバーアンダー（108/95 % FTP）、クリティカルパワー（110〜115 % FTP）3〜4分。伸ばしたパワーは、レースで自分のポジションのまま維持できるパワーです。 強度の高いセッションは週2回まで、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "4 hafta, haftada 50-75 dakikalık 3-4 seans, tüm eforlar TT''de: 10-20 dakika sweet spot (%88-92 FTP), 6-12 dakika eşik (%95-100 FTP), üst-alt (%108/95 FTP) ve 3-4 dakikada kritik güç (%110-115 FTP). Geliştirdiğin güç, yarışta kendi pozisyonunda koruyabileceğin güçtür. Haftada en fazla 2 yoğun seans, her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'threshold_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "4 semaines, 3 à 4 séances de 50 à 80 minutes. Intervalles longs de PMA (4 à 6 × 4'', 112-118 % FTP) et séries de 30/15 (120 % FTP) en position libre ; chaque récupération et chaque bloc final à 70 % FTP se font en TT. Une séance d''endurance TT par semaine. Au plus 2 séances intenses par semaine, chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "4 weeks, 3 to 4 sessions of 50 to 80 minutes. Long VO2max intervals (4 to 6 × 4'', 112-118% FTP) and 30/15 sets (120% FTP) in any position; every recovery and every final block at 70% FTP is in TT. One TT endurance session a week. At most 2 hard sessions a week, each with a dedicated warm-up; space them at least 48 h apart.", "es": "4 semanas, 3 a 4 sesiones de 50 a 80 minutos. Intervalos largos de VO2max (4 a 6 × 4'', 112-118 % FTP) y series 30/15 (120 % FTP) en posición libre; cada recuperación y cada bloque final al 70 % FTP se hacen en TT. Una sesión de resistencia TT por semana. Como máximo 2 sesiones intensas por semana, cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "4 settimane, da 3 a 4 sessioni da 50 a 80 minuti. Intervalli lunghi di VO2max (da 4 a 6 × 4'', 112-118 % FTP) e serie 30/15 (120 % FTP) in posizione libera; ogni recupero e ogni blocco finale al 70 % FTP si fanno in TT. Una sessione di resistenza TT a settimana. Al massimo 2 sessioni intense a settimana, ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "4 Wochen, 3 bis 4 Einheiten von 50 bis 80 Minuten. Lange VO2max-Intervalle (4 bis 6 × 4'', 112-118 % FTP) und 30/15-Serien (120 % FTP) in freier Position; jede Erholung und jeder Schlussblock bei 70 % FTP in TT. Eine TT-Ausdauereinheit pro Woche. Höchstens 2 intensive Einheiten pro Woche, jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "4 weken, 3 tot 4 sessies van 50 tot 80 minuten. Lange VO2max-intervallen (4 tot 6 × 4'', 112-118 % FTP) en 30/15-series (120 % FTP) in vrije houding; elk herstel en elk slotblok op 70 % FTP in TT. Eén TT-duursessie per week. Maximaal 2 intensieve sessies per week, elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "4 semanas, 3 a 4 sessões de 50 a 80 minutos. Intervalos longos de VO2max (4 a 6 × 4'', 112-118 % FTP) e séries 30/15 (120 % FTP) em posição livre; cada recuperação e cada bloco final a 70 % FTP são em TT. Uma sessão de resistência TT por semana. No máximo 2 sessões intensas por semana, cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "4週間、50〜80分のセッションを週3〜4回。ロングVO2maxインターバル（4〜6×4''、112〜118 % FTP）と30/15（120 % FTP）はポジション自由、回復と最後の70 % FTPブロックはすべてTT。週1回のTT持久セッション。 強度の高いセッションは週2回まで、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "4 hafta, haftada 50-80 dakikalık 3-4 seans. Serbest pozisyonda uzun VO2max intervalleri (4-6 × 4'', %112-118 FTP) ve 30/15 setleri (%120 FTP); her toparlanma ve %70 FTP''deki her son blok TT''de. Haftada bir TT dayanıklılık seansı. Haftada en fazla 2 yoğun seans, her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'vo2_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "8 semaines, deux cycles de 3 semaines de charge et 1 allégée, 3 à 4 séances de 55 à 135 minutes. Sprints assis de 15 à 20 s (170-180 % FTP), relances d''une minute (115-125 % FTP) et séries de 30/30 (130 % FTP), toujours en TT, plus deux séances d''endurance TT par semaine. Au plus 2 séances intenses par semaine (3 en semaine de pic), chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "8 weeks, two cycles of 3 loading weeks and 1 lighter week, 3 to 4 sessions of 55 to 135 minutes. Seated 15 to 20 s sprints (170-180% FTP), one-minute surges (115-125% FTP) and 30/30 sets (130% FTP), always in TT, plus two TT endurance sessions a week. At most 2 hard sessions a week (3 in peak weeks), each with a dedicated warm-up; space them at least 48 h apart.", "es": "8 semanas, dos ciclos de 3 semanas de carga y 1 más ligera, 3 a 4 sesiones de 55 a 135 minutos. Sprints sentado de 15 a 20 s (170-180 % FTP), cambios de ritmo de un minuto (115-125 % FTP) y series 30/30 (130 % FTP), siempre en TT, más dos sesiones de resistencia TT por semana. Como máximo 2 sesiones intensas por semana (3 en semana pico), cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "8 settimane, due cicli di 3 settimane di carico e 1 di scarico, da 3 a 4 sessioni da 55 a 135 minuti. Sprint seduti da 15 a 20 s (170-180 % FTP), rilanci di un minuto (115-125 % FTP) e serie 30/30 (130 % FTP), sempre in TT, più due sessioni di resistenza TT a settimana. Al massimo 2 sessioni intense a settimana (3 nella settimana di picco), ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "8 Wochen, zwei Zyklen aus 3 Belastungswochen und 1 Entlastungswoche, 3 bis 4 Einheiten von 55 bis 135 Minuten. Sitzende Sprints von 15 bis 20 s (170-180 % FTP), einminütige Antritte (115-125 % FTP) und 30/30-Serien (130 % FTP), immer in TT, dazu zwei TT-Ausdauereinheiten pro Woche. Höchstens 2 intensive Einheiten pro Woche (3 in der Spitzenwoche), jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "8 weken, twee cycli van 3 belastingsweken en 1 lichtere week, 3 tot 4 sessies van 55 tot 135 minuten. Zittende sprints van 15 tot 20 s (170-180 % FTP), versnellingen van een minuut (115-125 % FTP) en 30/30-series (130 % FTP), altijd in TT, plus twee TT-duursessies per week. Maximaal 2 intensieve sessies per week (3 in de piekweek), elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "8 semanas, dois ciclos de 3 semanas de carga e 1 mais leve, 3 a 4 sessões de 55 a 135 minutos. Sprints sentado de 15 a 20 s (170-180 % FTP), retomadas de um minuto (115-125 % FTP) e séries 30/30 (130 % FTP), sempre em TT, mais duas sessões de resistência TT por semana. No máximo 2 sessões intensas por semana (3 na semana de pico), cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "8週間、負荷3週＋軽め1週の2サイクル、55〜135分のセッションを週3〜4回。15〜20秒のシッティングスプリント（170〜180 % FTP）、1分の加速（115〜125 % FTP）、30/30（130 % FTP）を常にTTで。加えて週2回のTT持久セッション。 強度の高いセッションは週2回まで（ピーク週は3回）、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "8 hafta, 3 yüklenme + 1 hafif haftadan oluşan iki döngü, haftada 55-135 dakikalık 3-4 seans. Oturarak 15-20 sn sprintler (%170-180 FTP), bir dakikalık ataklar (%115-125 FTP) ve 30/30 setleri (%130 FTP), hep TT''de; ayrıca haftada iki TT dayanıklılık seansı. Haftada en fazla 2 yoğun seans (zirve haftasında 3), her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "12 semaines, trois cycles de 3 semaines de charge et 1 allégée, 3 à 4 séances de 55 à 135 minutes. Sprints assis de 15 à 20 s (170-180 % FTP), relances d''une minute (115-125 % FTP) et séries de 30/30 (130 % FTP), toujours en TT, plus deux séances d''endurance TT par semaine jusqu''à 75 minutes d''affilée. Au plus 2 séances intenses par semaine (3 en semaine de pic), chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "12 weeks, three cycles of 3 loading weeks and 1 lighter week, 3 to 4 sessions of 55 to 135 minutes. Seated 15 to 20 s sprints (170-180% FTP), one-minute surges (115-125% FTP) and 30/30 sets (130% FTP), always in TT, plus two TT endurance sessions a week up to 75 minutes in a row. At most 2 hard sessions a week (3 in peak weeks), each with a dedicated warm-up; space them at least 48 h apart.", "es": "12 semanas, tres ciclos de 3 semanas de carga y 1 más ligera, 3 a 4 sesiones de 55 a 135 minutos. Sprints sentado de 15 a 20 s (170-180 % FTP), cambios de ritmo de un minuto (115-125 % FTP) y series 30/30 (130 % FTP), siempre en TT, más dos sesiones de resistencia TT por semana de hasta 75 minutos seguidos. Como máximo 2 sesiones intensas por semana (3 en semana pico), cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "12 settimane, tre cicli di 3 settimane di carico e 1 di scarico, da 3 a 4 sessioni da 55 a 135 minuti. Sprint seduti da 15 a 20 s (170-180 % FTP), rilanci di un minuto (115-125 % FTP) e serie 30/30 (130 % FTP), sempre in TT, più due sessioni di resistenza TT a settimana fino a 75 minuti di fila. Al massimo 2 sessioni intense a settimana (3 nella settimana di picco), ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "12 Wochen, drei Zyklen aus 3 Belastungswochen und 1 Entlastungswoche, 3 bis 4 Einheiten von 55 bis 135 Minuten. Sitzende Sprints von 15 bis 20 s (170-180 % FTP), einminütige Antritte (115-125 % FTP) und 30/30-Serien (130 % FTP), immer in TT, dazu zwei TT-Ausdauereinheiten pro Woche bis 75 Minuten am Stück. Höchstens 2 intensive Einheiten pro Woche (3 in der Spitzenwoche), jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "12 weken, drie cycli van 3 belastingsweken en 1 lichtere week, 3 tot 4 sessies van 55 tot 135 minuten. Zittende sprints van 15 tot 20 s (170-180 % FTP), versnellingen van een minuut (115-125 % FTP) en 30/30-series (130 % FTP), altijd in TT, plus twee TT-duursessies per week tot 75 minuten aan één stuk. Maximaal 2 intensieve sessies per week (3 in de piekweek), elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "12 semanas, três ciclos de 3 semanas de carga e 1 mais leve, 3 a 4 sessões de 55 a 135 minutos. Sprints sentado de 15 a 20 s (170-180 % FTP), retomadas de um minuto (115-125 % FTP) e séries 30/30 (130 % FTP), sempre em TT, mais duas sessões de resistência TT por semana até 75 minutos seguidos. No máximo 2 sessões intensas por semana (3 na semana de pico), cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "12週間、負荷3週＋軽め1週の3サイクル、55〜135分のセッションを週3〜4回。15〜20秒のシッティングスプリント（170〜180 % FTP）、1分の加速（115〜125 % FTP）、30/30（130 % FTP）を常にTTで。加えて週2回、最大75分連続のTT持久セッション。 強度の高いセッションは週2回まで（ピーク週は3回）、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "12 hafta, 3 yüklenme + 1 hafif haftadan oluşan üç döngü, haftada 55-135 dakikalık 3-4 seans. Oturarak 15-20 sn sprintler (%170-180 FTP), bir dakikalık ataklar (%115-125 FTP) ve 30/30 setleri (%130 FTP), hep TT''de; ayrıca haftada iki aralıksız 75 dakikaya kadar TT dayanıklılık seansı. Haftada en fazla 2 yoğun seans (zirve haftasında 3), her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "8 semaines, deux cycles de 3 semaines de charge et 1 allégée, 3 à 4 séances de 55 à 135 minutes, tous les efforts en TT : sweet spot de 12 à 30 minutes, seuil de 6 à 20 minutes, sur-sous et puissance critique de 3 à 5 minutes. Au plus 2 séances intenses par semaine (3 en semaine de pic), chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "8 weeks, two cycles of 3 loading weeks and 1 lighter week, 3 to 4 sessions of 55 to 135 minutes, all efforts in TT: sweet spot from 12 to 30 minutes, threshold from 6 to 20 minutes, over-unders and critical power from 3 to 5 minutes. At most 2 hard sessions a week (3 in peak weeks), each with a dedicated warm-up; space them at least 48 h apart.", "es": "8 semanas, dos ciclos de 3 semanas de carga y 1 más ligera, 3 a 4 sesiones de 55 a 135 minutos, todos los esfuerzos en TT: sweet spot de 12 a 30 minutos, umbral de 6 a 20 minutos, sobre-bajo y potencia crítica de 3 a 5 minutos. Como máximo 2 sesiones intensas por semana (3 en semana pico), cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "8 settimane, due cicli di 3 settimane di carico e 1 di scarico, da 3 a 4 sessioni da 55 a 135 minuti, tutti gli sforzi in TT: sweet spot da 12 a 30 minuti, soglia da 6 a 20 minuti, sopra-sotto e potenza critica da 3 a 5 minuti. Al massimo 2 sessioni intense a settimana (3 nella settimana di picco), ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "8 Wochen, zwei Zyklen aus 3 Belastungswochen und 1 Entlastungswoche, 3 bis 4 Einheiten von 55 bis 135 Minuten, alle Belastungen in TT: Sweet Spot von 12 bis 30 Minuten, Schwelle von 6 bis 20 Minuten, Over-Under und kritische Leistung von 3 bis 5 Minuten. Höchstens 2 intensive Einheiten pro Woche (3 in der Spitzenwoche), jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "8 weken, twee cycli van 3 belastingsweken en 1 lichtere week, 3 tot 4 sessies van 55 tot 135 minuten, alle inspanningen in TT: sweet spot van 12 tot 30 minuten, drempel van 6 tot 20 minuten, over-unders en kritisch vermogen van 3 tot 5 minuten. Maximaal 2 intensieve sessies per week (3 in de piekweek), elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "8 semanas, dois ciclos de 3 semanas de carga e 1 mais leve, 3 a 4 sessões de 55 a 135 minutos, todos os esforços em TT: sweet spot de 12 a 30 minutos, limiar de 6 a 20 minutos, acima-abaixo e potência crítica de 3 a 5 minutos. No máximo 2 sessões intensas por semana (3 na semana de pico), cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "8週間、負荷3週＋軽め1週の2サイクル、55〜135分のセッションを週3〜4回、全ての努力をTTで：スイートスポット12〜30分、閾値6〜20分、オーバーアンダーとクリティカルパワー3〜5分。 強度の高いセッションは週2回まで（ピーク週は3回）、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "8 hafta, 3 yüklenme + 1 hafif haftadan oluşan iki döngü, haftada 55-135 dakikalık 3-4 seans, tüm eforlar TT''de: 12-30 dakika sweet spot, 6-20 dakika eşik, 3-5 dakika üst-alt ve kritik güç. Haftada en fazla 2 yoğun seans (zirve haftasında 3), her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "12 semaines, trois cycles de 3 semaines de charge et 1 allégée, 3 à 4 séances de 50 minutes à 2 h 20, tous les efforts en TT : sweet spot de 12 à 60 minutes, seuil de 6 à 30 minutes, sur-sous jusqu''à 5 séries et puissance critique de 3 à 6 minutes. Au plus 2 séances intenses par semaine (3 en semaine de pic), chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "12 weeks, three cycles of 3 loading weeks and 1 lighter week, 3 to 4 sessions of 50 minutes to 2 h 20, all efforts in TT: sweet spot from 12 to 60 minutes, threshold from 6 to 30 minutes, over-unders up to 5 sets and critical power from 3 to 6 minutes. At most 2 hard sessions a week (3 in peak weeks), each with a dedicated warm-up; space them at least 48 h apart.", "es": "12 semanas, tres ciclos de 3 semanas de carga y 1 más ligera, 3 a 4 sesiones de 50 minutos a 2 h 20, todos los esfuerzos en TT: sweet spot de 12 a 60 minutos, umbral de 6 a 30 minutos, sobre-bajo hasta 5 series y potencia crítica de 3 a 6 minutos. Como máximo 2 sesiones intensas por semana (3 en semana pico), cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "12 settimane, tre cicli di 3 settimane di carico e 1 di scarico, da 3 a 4 sessioni da 50 minuti a 2 h 20, tutti gli sforzi in TT: sweet spot da 12 a 60 minuti, soglia da 6 a 30 minuti, sopra-sotto fino a 5 serie e potenza critica da 3 a 6 minuti. Al massimo 2 sessioni intense a settimana (3 nella settimana di picco), ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "12 Wochen, drei Zyklen aus 3 Belastungswochen und 1 Entlastungswoche, 3 bis 4 Einheiten von 50 Minuten bis 2 h 20, alle Belastungen in TT: Sweet Spot von 12 bis 60 Minuten, Schwelle von 6 bis 30 Minuten, Over-Under bis 5 Serien und kritische Leistung von 3 bis 6 Minuten. Höchstens 2 intensive Einheiten pro Woche (3 in der Spitzenwoche), jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "12 weken, drie cycli van 3 belastingsweken en 1 lichtere week, 3 tot 4 sessies van 50 minuten tot 2 u 20, alle inspanningen in TT: sweet spot van 12 tot 60 minuten, drempel van 6 tot 30 minuten, over-unders tot 5 series en kritisch vermogen van 3 tot 6 minuten. Maximaal 2 intensieve sessies per week (3 in de piekweek), elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "12 semanas, três ciclos de 3 semanas de carga e 1 mais leve, 3 a 4 sessões de 50 minutos a 2 h 20, todos os esforços em TT: sweet spot de 12 a 60 minutos, limiar de 6 a 30 minutos, acima-abaixo até 5 séries e potência crítica de 3 a 6 minutos. No máximo 2 sessões intensas por semana (3 na semana de pico), cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "12週間、負荷3週＋軽め1週の3サイクル、50分〜2時間20分のセッションを週3〜4回、全ての努力をTTで：スイートスポット12〜60分、閾値6〜30分、オーバーアンダー最大5セット、クリティカルパワー3〜6分。 強度の高いセッションは週2回まで（ピーク週は3回）、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "12 hafta, 3 yüklenme + 1 hafif haftadan oluşan üç döngü, haftada 50 dakika ile 2 sa 20 arası 3-4 seans, tüm eforlar TT''de: 12-60 dakika sweet spot, 6-30 dakika eşik, 5 sete kadar üst-alt ve 3-6 dakika kritik güç. Haftada en fazla 2 yoğun seans (zirve haftasında 3), her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "8 semaines pour un CLM de 10 à 20 km ou le vélo d''un triathlon S. Seuil, PMA et puissance critique, une simulation d''allure CLM par semaine (de 3×6'' à 25'' d''affilée) et une sortie d''endurance TT. Semaine 8 : affûtage avant la course. Au plus 2 séances intenses par semaine (3 en semaine de pic), chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "8 weeks for a 10 to 20 km TT or the bike leg of a sprint triathlon. Threshold, VO2max and critical power, one TT race-pace simulation a week (from 3×6'' to 25'' in a row) and one TT endurance ride. Week 8: taper before the race. At most 2 hard sessions a week (3 in peak weeks), each with a dedicated warm-up; space them at least 48 h apart.", "es": "8 semanas para una CRI de 10 a 20 km o la bici de un triatlón sprint. Umbral, VO2max y potencia crítica, una simulación de ritmo de CRI por semana (de 3×6'' a 25'' seguidos) y una salida de resistencia TT. Semana 8: puesta a punto antes de la carrera. Como máximo 2 sesiones intensas por semana (3 en semana pico), cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "8 settimane per una crono da 10 a 20 km o la frazione bici di un triathlon sprint. Soglia, VO2max e potenza critica, una simulazione a ritmo crono a settimana (da 3×6'' a 25'' di fila) e un''uscita di resistenza TT. Settimana 8: scarico prima della gara. Al massimo 2 sessioni intense a settimana (3 nella settimana di picco), ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "8 Wochen für ein 10- bis 20-km-Zeitfahren oder die Radstrecke eines Sprinttriathlons. Schwelle, VO2max und kritische Leistung, eine Renntempo-Simulation pro Woche (von 3×6'' bis 25'' am Stück) und eine TT-Ausdauerfahrt. Woche 8: Tapering vor dem Rennen. Höchstens 2 intensive Einheiten pro Woche (3 in der Spitzenwoche), jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "8 weken voor een tijdrit van 10 tot 20 km of het fietsdeel van een sprinttriatlon. Drempel, VO2max en kritisch vermogen, één simulatie op tijdrittempo per week (van 3×6'' tot 25'' aan één stuk) en één TT-duurrit. Week 8: taperen voor de wedstrijd. Maximaal 2 intensieve sessies per week (3 in de piekweek), elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "8 semanas para um contrarrelógio de 10 a 20 km ou a bike de um triatlo sprint. Limiar, VO2max e potência crítica, uma simulação de ritmo de contrarrelógio por semana (de 3×6'' a 25'' seguidos) e um treino de resistência TT. Semana 8: polimento antes da prova. No máximo 2 sessões intensas por semana (3 na semana de pico), cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "10〜20 kmのTTやスプリント・トライアスロンのバイクのための8週間。閾値、VO2max、クリティカルパワー、週1回のTTレースペース・シミュレーション（3×6''から25''連続まで）とTT持久ライド。8週目はレース前の調整。 強度の高いセッションは週2回まで（ピーク週は3回）、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "10-20 km''lik zamana karşı ya da sprint triatlonun bisiklet etabı için 8 hafta. Eşik, VO2max ve kritik güç, haftada bir zamana karşı temposu simülasyonu (3×6''''den aralıksız 25''''ye) ve bir TT dayanıklılık sürüşü. 8. hafta: yarış öncesi toparlanma. Haftada en fazla 2 yoğun seans (zirve haftasında 3), her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'clm_short_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "12 semaines pour un CLM de 40 km ou de 50 à 70 minutes. Sweet spot jusqu''à 75 minutes, seuil en TT de 2×10'' à 50'' d''affilée, PMA et puissance critique, une sortie longue TT par semaine jusqu''à 2 h 35. Semaine 12 : affûtage avant la course. Au plus 2 séances intenses par semaine (3 en semaine de pic), chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "12 weeks for a 40 km TT or a 50 to 70 minute effort. Sweet spot up to 75 minutes, threshold in TT from 2×10'' to 50'' in a row, VO2max and critical power, one long TT ride a week up to 2 h 35. Week 12: taper before the race. At most 2 hard sessions a week (3 in peak weeks), each with a dedicated warm-up; space them at least 48 h apart.", "es": "12 semanas para una CRI de 40 km o de 50 a 70 minutos. Sweet spot hasta 75 minutos, umbral en TT de 2×10'' a 50'' seguidos, VO2max y potencia crítica, una salida larga TT por semana hasta 2 h 35. Semana 12: puesta a punto antes de la carrera. Como máximo 2 sesiones intensas por semana (3 en semana pico), cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "12 settimane per una crono da 40 km o da 50 a 70 minuti. Sweet spot fino a 75 minuti, soglia in TT da 2×10'' a 50'' di fila, VO2max e potenza critica, un''uscita lunga TT a settimana fino a 2 h 35. Settimana 12: scarico prima della gara. Al massimo 2 sessioni intense a settimana (3 nella settimana di picco), ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "12 Wochen für ein 40-km-Zeitfahren oder 50 bis 70 Minuten. Sweet Spot bis 75 Minuten, Schwelle in TT von 2×10'' bis 50'' am Stück, VO2max und kritische Leistung, eine lange TT-Fahrt pro Woche bis 2 h 35. Woche 12: Tapering vor dem Rennen. Höchstens 2 intensive Einheiten pro Woche (3 in der Spitzenwoche), jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "12 weken voor een tijdrit van 40 km of van 50 tot 70 minuten. Sweet spot tot 75 minuten, drempel in TT van 2×10'' tot 50'' aan één stuk, VO2max en kritisch vermogen, één lange TT-rit per week tot 2 u 35. Week 12: taperen voor de wedstrijd. Maximaal 2 intensieve sessies per week (3 in de piekweek), elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "12 semanas para um contrarrelógio de 40 km ou de 50 a 70 minutos. Sweet spot até 75 minutos, limiar em TT de 2×10'' a 50'' seguidos, VO2max e potência crítica, um treino longo TT por semana até 2 h 35. Semana 12: polimento antes da prova. No máximo 2 sessões intensas por semana (3 na semana de pico), cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "40 kmまたは50〜70分のTTのための12週間。スイートスポットは最大75分、TTでの閾値は2×10''から50''連続まで、VO2maxとクリティカルパワー、週1回最大2時間35分のロングTTライド。12週目はレース前の調整。 強度の高いセッションは週2回まで（ピーク週は3回）、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "40 km''lik ya da 50-70 dakikalık zamana karşı için 12 hafta. 75 dakikaya kadar sweet spot, TT''de 2×10''''dan aralıksız 50''''ya eşik, VO2max ve kritik güç, haftada bir 2 sa 35''e kadar uzun TT sürüşü. 12. hafta: yarış öncesi toparlanma. Haftada en fazla 2 yoğun seans (zirve haftasında 3), her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "8 semaines pour le vélo d''un triathlon M (40 km). Allure triathlon en TT de 2×15'' à 60'' d''affilée, sweet spot et seuil, une séance de PMA et une sortie longue TT jusqu''à 2 h 35. Semaine 8 : affûtage avant la course. Au plus 2 séances intenses par semaine, chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "8 weeks for the bike leg of an Olympic-distance triathlon (40 km). Triathlon pace in TT from 2×15'' to 60'' in a row, sweet spot and threshold, one VO2max session and one long TT ride up to 2 h 35. Week 8: taper before the race. At most 2 hard sessions a week, each with a dedicated warm-up; space them at least 48 h apart.", "es": "8 semanas para la bici de un triatlón olímpico (40 km). Ritmo de triatlón en TT de 2×15'' a 60'' seguidos, sweet spot y umbral, una sesión de VO2max y una salida larga TT hasta 2 h 35. Semana 8: puesta a punto antes de la carrera. Como máximo 2 sesiones intensas por semana, cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "8 settimane per la frazione bici di un triathlon olimpico (40 km). Ritmo triathlon in TT da 2×15'' a 60'' di fila, sweet spot e soglia, una sessione di VO2max e un''uscita lunga TT fino a 2 h 35. Settimana 8: scarico prima della gara. Al massimo 2 sessioni intense a settimana, ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "8 Wochen für die Radstrecke einer olympischen Distanz (40 km). Triathlontempo in TT von 2×15'' bis 60'' am Stück, Sweet Spot und Schwelle, eine VO2max-Einheit und eine lange TT-Fahrt bis 2 h 35. Woche 8: Tapering vor dem Rennen. Höchstens 2 intensive Einheiten pro Woche, jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "8 weken voor het fietsdeel van een olympische triatlon (40 km). Triatlontempo in TT van 2×15'' tot 60'' aan één stuk, sweet spot en drempel, één VO2max-sessie en één lange TT-rit tot 2 u 35. Week 8: taperen voor de wedstrijd. Maximaal 2 intensieve sessies per week, elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "8 semanas para a bike de um triatlo olímpico (40 km). Ritmo de triatlo em TT de 2×15'' a 60'' seguidos, sweet spot e limiar, uma sessão de VO2max e um treino longo TT até 2 h 35. Semana 8: polimento antes da prova. No máximo 2 sessões intensas por semana, cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "オリンピックディスタンス（40 km）のバイクのための8週間。TTでのトライアスロンペースは2×15''から60''連続まで、スイートスポットと閾値、VO2maxセッション1回、最大2時間35分のロングTTライド。8週目はレース前の調整。 強度の高いセッションは週2回まで、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "Olimpik mesafe triatlonun bisiklet etabı (40 km) için 8 hafta. TT''de triatlon temposu 2×15''''den aralıksız 60''''ye, sweet spot ve eşik, bir VO2max seansı ve 2 sa 35''e kadar uzun TT sürüşü. 8. hafta: yarış öncesi toparlanma. Haftada en fazla 2 yoğun seans, her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'triathlon_m_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{description}', '{"fr": "12 semaines pour le vélo d''un 70.3 ou d''un Ironman. Allure triathlon en TT de 2×15'' à 90'' d''affilée, tempo jusqu''à 75 minutes, sweet spot et PMA, une sortie longue TT par semaine jusqu''à 2 h 50. Semaine 12 : affûtage avant la course. Au plus 2 séances intenses par semaine, chacune précédée d''un échauffement adapté ; espace-les d''au moins 48 h.", "en": "12 weeks for the bike leg of a 70.3 or an Ironman. Triathlon pace in TT from 2×15'' to 90'' in a row, tempo up to 75 minutes, sweet spot and VO2max, one long TT ride a week up to 2 h 50. Week 12: taper before the race. At most 2 hard sessions a week, each with a dedicated warm-up; space them at least 48 h apart.", "es": "12 semanas para la bici de un 70.3 o un Ironman. Ritmo de triatlón en TT de 2×15'' a 90'' seguidos, tempo hasta 75 minutos, sweet spot y VO2max, una salida larga TT por semana hasta 2 h 50. Semana 12: puesta a punto antes de la carrera. Como máximo 2 sesiones intensas por semana, cada una con un calentamiento adaptado; sepáralas al menos 48 h.", "it": "12 settimane per la frazione bici di un 70.3 o di un Ironman. Ritmo triathlon in TT da 2×15'' a 90'' di fila, tempo fino a 75 minuti, sweet spot e VO2max, un''uscita lunga TT a settimana fino a 2 h 50. Settimana 12: scarico prima della gara. Al massimo 2 sessioni intense a settimana, ognuna con un riscaldamento dedicato; distanziale di almeno 48 h.", "de": "12 Wochen für die Radstrecke eines 70.3 oder Ironman. Triathlontempo in TT von 2×15'' bis 90'' am Stück, Tempo bis 75 Minuten, Sweet Spot und VO2max, eine lange TT-Fahrt pro Woche bis 2 h 50. Woche 12: Tapering vor dem Rennen. Höchstens 2 intensive Einheiten pro Woche, jede mit passendem Aufwärmen; lass mindestens 48 h dazwischen.", "nl": "12 weken voor het fietsdeel van een 70.3 of een Ironman. Triatlontempo in TT van 2×15'' tot 90'' aan één stuk, tempo tot 75 minuten, sweet spot en VO2max, één lange TT-rit per week tot 2 u 50. Week 12: taperen voor de wedstrijd. Maximaal 2 intensieve sessies per week, elk met een aangepaste warming-up; laat er minstens 48 u tussen.", "pt": "12 semanas para a bike de um 70.3 ou de um Ironman. Ritmo de triatlo em TT de 2×15'' a 90'' seguidos, tempo até 75 minutos, sweet spot e VO2max, um treino longo TT por semana até 2 h 50. Semana 12: polimento antes da prova. No máximo 2 sessões intensas por semana, cada uma com um aquecimento adequado; espace-as em pelo menos 48 h.", "ja": "70.3やアイアンマンのバイクのための12週間。TTでのトライアスロンペースは2×15''から90''連続まで、テンポは最大75分、スイートスポットとVO2max、週1回最大2時間50分のロングTTライド。12週目はレース前の調整。 強度の高いセッションは週2回まで、それぞれ専用のウォームアップ付き。間は48時間以上空ける。", "tr": "70.3 ya da Ironman bisiklet etabı için 12 hafta. TT''de triatlon temposu 2×15''''den aralıksız 90''''ya, 75 dakikaya kadar tempo, sweet spot ve VO2max, haftada bir 2 sa 50''ye kadar uzun TT sürüşü. 12. hafta: yarış öncesi toparlanma. Haftada en fazla 2 yoğun seans, her biri uygun bir ısınmayla; aralarında en az 48 saat bırak."}'::jsonb) WHERE name_key = 'triathlon_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Découverte : 8 sprints assis de 15'''' et 6 relances d''1'' en TT, séparés par une endurance TT. On apprend à pousser fort sans lever la tête ni lâcher les prolongateurs.", "en": "Discovery: 8 seated 15'''' sprints and 6 one-minute surges in TT, separated by a TT endurance ride. You learn to push hard without lifting your head or letting go of the extensions.", "es": "Descubrimiento: 8 sprints sentado de 15'''' y 6 cambios de ritmo de 1'' en TT, separados por una resistencia en TT. Aprendes a empujar fuerte sin levantar la cabeza ni soltar los acoples.", "it": "Scoperta: 8 sprint da seduto di 15'''' e 6 rilanci di 1'' in TT, separati da un endurance in TT. Impari a spingere forte senza alzare la testa né lasciare le protesi.", "pt": "Descoberta: 8 sprints sentado de 15'''' e 6 retomadas de 1'' em TT, separados por um endurance em TT. Você aprende a empurrar forte sem levantar a cabeça nem soltar o clipe.", "de": "Kennenlernen: 8 Sitzsprints à 15'''' und 6 Antritte à 1'' in TT, getrennt durch eine TT-Grundlageneinheit. Du lernst, hart zu treten, ohne den Kopf zu heben oder den Aufsatz loszulassen.", "nl": "Kennismaking: 8 zittende sprints van 15'''' en 6 versnellingen van 1'' in TT, gescheiden door een duurtraining in TT. Je leert hard trappen zonder je hoofd op te tillen of de opzetstukken los te laten.", "ja": "導入：シッティングで15''''のスプリント8本と、TTで1''の加速6本。間にTTでのエンデュランスを挟みます。頭を上げずエアロバーを離さずに強く踏むことを学びます。", "tr": "Keşif: oturarak 8 adet 15'''' sprint ve TT''de 6 adet 1'' atak, araya bir TT dayanıklılık. Başını kaldırmadan ve uzatmaları bırakmadan sert basmayı öğreniyorsun."}'::jsonb) WHERE name_key = 'sprint_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "10 sprints, 8 relances et une sortie longue en TT. Deux séances dures seulement : la puissance max se développe sur des jambes fraîches, pas fatiguées.", "en": "10 sprints, 8 surges and a long ride in TT. Only two hard sessions: max power develops on fresh legs, not tired ones.", "es": "10 sprints, 8 cambios de ritmo y una salida larga en TT. Solo dos sesiones duras: la potencia máxima se desarrolla con piernas frescas, no cansadas.", "it": "10 sprint, 8 rilanci e un''uscita lunga in TT. Solo due sedute dure: la potenza massima si sviluppa su gambe fresche, non stanche.", "pt": "10 sprints, 8 retomadas e um treino longo em TT. Só duas sessões duras: a potência máxima se desenvolve com pernas descansadas, não cansadas.", "de": "10 Sprints, 8 Antritte und eine lange Fahrt in TT. Nur zwei harte Einheiten: Maximalleistung entwickelt sich auf frischen Beinen, nicht auf müden.", "nl": "10 sprints, 8 versnellingen en een lange rit in TT. Slechts twee zware trainingen: maximaal vermogen ontwikkel je op frisse benen, niet op vermoeide.", "ja": "スプリント10本、加速8本、TTでのロングライド。きついセッションは2回だけ：最大パワーは疲れた脚ではなくフレッシュな脚で伸びます。", "tr": "10 sprint, 8 atak ve TT''de bir uzun sürüş. Sadece iki zor antrenman: maksimum güç yorgun değil, taze bacaklarla gelişir."}'::jsonb) WHERE name_key = 'sprint_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Semaine la plus dure : 3 séries de 30/30 et des sprints de 20''''. Les deux séances d''endurance TT entretiennent la tenue de position sans entamer la fraîcheur.", "en": "Hardest week: 3 sets of 30/30 and 20'''' sprints. The two TT endurance sessions maintain your position hold without cutting into your freshness.", "es": "Semana más dura: 3 series de 30/30 y sprints de 20''''. Las dos sesiones de resistencia en TT mantienen la posición sin restarte frescura.", "it": "Settimana più dura: 3 serie di 30/30 e sprint di 20''''. Le due sedute di endurance in TT mantengono la tenuta della posizione senza intaccare la freschezza.", "pt": "Semana mais dura: 3 séries de 30/30 e sprints de 20''''. As duas sessões de endurance em TT mantêm a sustentação da posição sem tirar sua disposição.", "de": "Die härteste Woche: 3 Serien 30/30 und 20''''-Sprints. Die beiden TT-Grundlageneinheiten erhalten das Halten der Position, ohne die Frische anzugreifen.", "nl": "De zwaarste week: 3 series 30/30 en sprints van 20''''. De twee duurtrainingen in TT onderhouden het vasthouden van de houding zonder de frisheid aan te tasten.", "ja": "最もきつい週：30/30を3セットと20''''のスプリント。2回のTTでのエンデュランスは、フレッシュさを損なわずにポジション維持力を保ちます。", "tr": "En zor hafta: 3 set 30/30 ve 20'''' sprintler. İki TT dayanıklılık antrenmanı tazeliği bozmadan pozisyon tutuşunu korur."}'::jsonb) WHERE name_key = 'sprint_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Allègement : moins de répétitions, une endurance TT de 40''. Tes sprints doivent sortir plus fort qu''en semaine 1, c''est le signe que le travail a pris.", "en": "Lighter week: fewer reps, a 40'' TT endurance ride. Your sprints should come out stronger than in week 1, the sign that the work has paid off.", "es": "Semana más ligera: menos repeticiones, una resistencia en TT de 40''. Tus sprints deben salir más fuertes que en la semana 1, señal de que el trabajo ha surtido efecto.", "it": "Settimana di scarico: meno ripetute, un endurance in TT di 40''. I tuoi sprint devono uscire più forti che in settimana 1: è il segno che il lavoro ha fatto effetto.", "pt": "Semana mais leve: menos repetições, um endurance em TT de 40''. Seus sprints devem sair mais fortes que na semana 1, é o sinal de que o trabalho deu resultado.", "de": "Entlastung: weniger Wiederholungen, 40'' TT-Grundlage. Deine Sprints sollten stärker ausfallen als in Woche 1 – das Zeichen, dass das Training gewirkt hat.", "nl": "Afbouw: minder herhalingen, 40'' duur in TT. Je sprints moeten krachtiger zijn dan in week 1: het teken dat de training is aangeslagen.", "ja": "軽めの週：反復を減らし、TTでのエンデュランス40''。スプリントは1週目より強く出るはずで、それがトレーニングの効果の証です。", "tr": "Hafifletme: daha az tekrar, 40'' TT dayanıklılık. Sprintlerin 1. haftadakinden daha güçlü çıkmalı, çalışmanın tuttuğunun işareti bu."}'::jsonb) WHERE name_key = 'sprint_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Mise en route : sweet spot 3×10'' et seuil 4×6'' en TT, séparés par une endurance TT. On mesure ce que tu produis couché avant d''allonger les blocs.", "en": "Getting started: sweet spot 3×10'' and threshold 4×6'' in TT, separated by a TT endurance ride. We measure what you produce tucked low before lengthening the blocks.", "es": "Puesta en marcha: sweet spot 3×10'' y umbral 4×6'' en TT, separados por una resistencia en TT. Medimos lo que produces acoplado antes de alargar los bloques.", "it": "Avvio: sweet spot 3×10'' e soglia 4×6'' in TT, separati da un endurance in TT. Misuriamo ciò che produci in posizione aero prima di allungare i blocchi.", "pt": "Início: sweet spot 3×10'' e limiar 4×6'' em TT, separados por um endurance em TT. Medimos o que você produz em posição aero antes de alongar os blocos.", "de": "Einstieg: Sweet Spot 3×10'' und Schwelle 4×6'' in TT, getrennt durch eine TT-Grundlageneinheit. Wir messen, was du liegend leistest, bevor die Blöcke länger werden.", "nl": "Instap: sweet spot 3×10'' en drempel 4×6'' in TT, gescheiden door een duurtraining in TT. We meten wat je liggend levert voordat de blokken langer worden.", "ja": "導入：TTでスイートスポット3×10''と閾値4×6''、間にTTでのエンデュランス。ブロックを伸ばす前に、伏せた姿勢で出せるパワーを測ります。", "tr": "Başlangıç: TT''de sweet spot 3×10'' ve eşik 4×6'', araya bir TT dayanıklılık. Blokları uzatmadan önce yatık pozisyonda ne ürettiğini ölçüyoruz."}'::jsonb) WHERE name_key = 'threshold_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "Sweet spot 3×12'' et premiers sur-sous : changer d''intensité sans bouger de position. Le tempo et la sortie longue en TT font travailler la position sans fatigue.", "en": "Sweet spot 3×12'' and first over-unders: changing intensity without moving out of position. Tempo and the long ride in TT work your position without fatigue.", "es": "Sweet spot 3×12'' y primeros sobre-bajo: cambiar de intensidad sin moverte de la posición. El tempo y la salida larga en TT trabajan la posición sin fatiga.", "it": "Sweet spot 3×12'' e primi sopra-sotto: cambiare intensità senza muoversi dalla posizione. Il ritmo tempo e l''uscita lunga in TT allenano la posizione senza fatica.", "pt": "Sweet spot 3×12'' e primeiros acima-abaixo: mudar de intensidade sem sair da posição. O ritmo tempo e o treino longo em TT trabalham a posição sem cansaço.", "de": "Sweet Spot 3×12'' und erste Over-Under: die Intensität wechseln, ohne die Position zu verändern. Tempo und lange Fahrt in TT trainieren die Position ohne Ermüdung.", "nl": "Sweet spot 3×12'' en eerste over-unders: van intensiteit wisselen zonder je houding te veranderen. Het tempo en de lange rit in TT trainen de houding zonder vermoeidheid.", "ja": "スイートスポット3×12''と最初のオーバーアンダー：ポジションを動かさずに強度を変えます。TTでのテンポとロングライドは、疲労なしにポジションを鍛えます。", "tr": "Sweet spot 3×12'' ve ilk üst-altlar: pozisyonu bozmadan yoğunluk değiştirmek. TT''de tempo ve uzun sürüş, pozisyonu yorgunluk olmadan çalıştırır."}'::jsonb) WHERE name_key = 'threshold_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Semaine la plus chargée : 3×12'' au seuil et 5×4'' à la puissance critique. Les deux autres séances restent faciles pour que la qualité des blocs durs soit au rendez-vous.", "en": "Heaviest week: 3×12'' at threshold and 5×4'' at critical power. The other two sessions stay easy so the hard blocks are high quality.", "es": "Semana más cargada: 3×12'' al umbral y 5×4'' a potencia crítica. Las otras dos sesiones siguen siendo fáciles para que los bloques duros salgan con calidad.", "it": "Settimana più carica: 3×12'' in soglia e 5×4'' alla potenza critica. Le altre due sedute restano facili perché la qualità dei blocchi duri ci sia.", "pt": "Semana mais carregada: 3×12'' no limiar e 5×4'' na potência crítica. As outras duas sessões continuam fáceis para que os blocos duros tenham qualidade.", "de": "Die intensivste Woche: 3×12'' an der Schwelle und 5×4'' bei kritischer Leistung. Die beiden anderen Einheiten bleiben locker, damit die harten Blöcke Qualität haben.", "nl": "De zwaarste week: 3×12'' op drempel en 5×4'' op kritisch vermogen. De twee andere trainingen blijven makkelijk, zodat de zware blokken kwaliteit hebben.", "ja": "最も負荷の高い週：閾値3×12''とクリティカルパワー5×4''。きついブロックの質を確保するため、他の2セッションは楽に保ちます。", "tr": "En yüklü hafta: eşikte 3×12'' ve kritik güçte 5×4''. Zor blokların kaliteli olması için diğer iki antrenman kolay kalır."}'::jsonb) WHERE name_key = 'threshold_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Volume réduit pour assimiler, intensité gardée sur des blocs courts. Les mêmes watts en TT doivent te sembler plus faciles qu''en semaine 1.", "en": "Reduced volume to absorb the work, intensity kept on short blocks. The same watts in TT should feel easier than in week 1.", "es": "Volumen reducido para asimilar, intensidad mantenida en bloques cortos. Los mismos vatios en TT deben parecerte más fáciles que en la semana 1.", "it": "Volume ridotto per assimilare, intensità mantenuta su blocchi brevi. Gli stessi watt in TT devono sembrarti più facili che in settimana 1.", "pt": "Volume reduzido para assimilar, intensidade mantida em blocos curtos. Os mesmos watts em TT devem parecer mais fáceis que na semana 1.", "de": "Reduzierter Umfang zum Verarbeiten, Intensität auf kurzen Blöcken beibehalten. Dieselben Watt in TT sollten sich leichter anfühlen als in Woche 1.", "nl": "Minder volume om te verwerken, intensiteit behouden op korte blokken. Dezelfde watts in TT moeten makkelijker aanvoelen dan in week 1.", "ja": "吸収のためにボリュームを減らし、短いブロックで強度は維持。TTでの同じワット数が1週目より楽に感じられるはずです。", "tr": "Özümsemek için hacim azaltıldı, kısa bloklarda yoğunluk korunuyor. TT''de aynı watt 1. haftadakinden daha kolay gelmeli."}'::jsonb) WHERE name_key = 'threshold_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "Une répétition de plus sur chaque séance de PMA, séparées par une endurance TT, et une sortie longue en TT. Reprendre la position en moins de 5 s après chaque effort devient un réflexe.", "en": "One more rep in each VO2max session, separated by a TT endurance ride, plus a long ride in TT. Getting back into position within 5 s after each effort becomes a reflex.", "es": "Una repetición más en cada sesión de VO2max, separadas por una resistencia en TT, y una salida larga en TT. Recuperar la posición en menos de 5 s tras cada esfuerzo se vuelve un reflejo.", "it": "Una ripetuta in più in ogni seduta di VO2max, separate da un endurance in TT, e un''uscita lunga in TT. Riprendere la posizione in meno di 5 s dopo ogni sforzo diventa un riflesso.", "pt": "Uma repetição a mais em cada sessão de VO2max, separadas por um endurance em TT, e um treino longo em TT. Retomar a posição em menos de 5 s após cada esforço vira um reflexo.", "de": "Eine Wiederholung mehr in jeder VO2max-Einheit, getrennt durch eine TT-Grundlageneinheit, dazu eine lange Fahrt in TT. Die Position in weniger als 5 s nach jeder Belastung wieder einzunehmen, wird zum Reflex.", "nl": "Eén herhaling meer in elke VO2max-training, gescheiden door een duurtraining in TT, plus een lange rit in TT. Binnen 5 s na elke inspanning je houding hervatten wordt een reflex.", "ja": "各VO2maxセッションで1本ずつ追加し、間にTTでのエンデュランス、さらにTTでのロングライド。各努力の後5 s以内にポジションに戻ることが反射になります。", "tr": "Her VO2max antrenmanında bir tekrar fazla, araya bir TT dayanıklılık, ayrıca TT''de bir uzun sürüş. Her efordan sonra 5 s içinde pozisyona dönmek bir refleks haline gelir."}'::jsonb) WHERE name_key = 'vo2_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Semaine la plus chargée : 6×4'' et 30/15 en 3 séries, avec une endurance et une sortie longue en TT entre les deux. La PMA monte, ta position de récupération doit tenir même quand tout brûle.", "en": "Heaviest week: 6×4'' and 30/15 in 3 sets, with an endurance ride and a long ride in TT in between. VO2max rises; your recovery position must hold even when everything burns.", "es": "Semana más cargada: 6×4'' y 30/15 en 3 series, con una resistencia y una salida larga en TT entre ambas. El VO2max sube; tu posición de recuperación debe aguantar aunque todo queme.", "it": "Settimana più carica: 6×4'' e 30/15 in 3 serie, con un endurance e un''uscita lunga in TT nel mezzo. Il VO2max sale, la tua posizione di recupero deve tenere anche quando tutto brucia.", "pt": "Semana mais carregada: 6×4'' e 30/15 em 3 séries, com um endurance e um treino longo em TT entre as duas. O VO2max sobe; sua posição de recuperação precisa aguentar mesmo quando tudo queima.", "de": "Die intensivste Woche: 6×4'' und 30/15 in 3 Serien, dazwischen eine Grundlageneinheit und eine lange Fahrt in TT. VO2max steigt, deine Erholungsposition muss halten, auch wenn alles brennt.", "nl": "De zwaarste week: 6×4'' en 30/15 in 3 series, met daartussen een duurtraining en een lange rit in TT. De VO2max stijgt, je herstelhouding moet standhouden, ook als alles brandt.", "ja": "最も負荷の高い週：6×4''と30/15を3セット、その間にTTでのエンデュランスとロングライド。VO2maxが上がり、すべてが焼けるようでも回復時のポジションを保つ必要があります。", "tr": "En yüklü hafta: 6×4'' ve 3 set 30/15, arada TT''de bir dayanıklılık ve bir uzun sürüş. VO2max yükseliyor, her şey yanarken bile toparlanma pozisyonun tutmalı."}'::jsonb) WHERE name_key = 'vo2_tt_4w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Découverte : sprints de 15'''' et relances d''1'' en TT, séparés par une endurance TT, plus une sortie longue. On apprend le geste explosif en position.", "en": "Discovery: 15'''' sprints and one-minute surges in TT, separated by a TT endurance ride, plus a long ride. You learn the explosive movement in position.", "es": "Descubrimiento: sprints de 15'''' y cambios de ritmo de 1'' en TT, separados por una resistencia en TT, más una salida larga. Aprendes el gesto explosivo en posición.", "it": "Scoperta: sprint di 15'''' e rilanci di 1'' in TT, separati da un endurance in TT, più un''uscita lunga. Impari il gesto esplosivo in posizione.", "pt": "Descoberta: sprints de 15'''' e retomadas de 1'' em TT, separados por um endurance em TT, mais um treino longo. Você aprende o gesto explosivo na posição.", "de": "Kennenlernen: 15''''-Sprints und Antritte à 1'' in TT, getrennt durch eine TT-Grundlageneinheit, dazu eine lange Fahrt. Du lernst die explosive Bewegung in Position.", "nl": "Kennismaking: sprints van 15'''' en versnellingen van 1'' in TT, gescheiden door een duurtraining in TT, plus een lange rit. Je leert de explosieve beweging in houding.", "ja": "導入：TTで15''''のスプリントと1''の加速、間にTTでのエンデュランス、さらにロングライド。ポジションを保ったまま爆発的な動きを学びます。", "tr": "Keşif: TT''de 15'''' sprintler ve 1'' ataklar, araya bir TT dayanıklılık, ayrıca bir uzun sürüş. Pozisyonda patlayıcı hareketi öğreniyorsun."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "10 sprints et les premiers 30/30. Deux séances dures par semaine suffisent : la puissance max se travaille sur des jambes fraîches.", "en": "10 sprints and the first 30/30s. Two hard sessions a week are enough: max power is trained on fresh legs.", "es": "10 sprints y los primeros 30/30. Dos sesiones duras por semana bastan: la potencia máxima se trabaja con piernas frescas.", "it": "10 sprint e i primi 30/30. Due sedute dure a settimana bastano: la potenza massima si allena su gambe fresche.", "pt": "10 sprints e os primeiros 30/30. Duas sessões duras por semana bastam: a potência máxima se treina com pernas descansadas.", "de": "10 Sprints und die ersten 30/30. Zwei harte Einheiten pro Woche reichen: Maximalleistung trainierst du auf frischen Beinen.", "nl": "10 sprints en de eerste 30/30''s. Twee zware trainingen per week volstaan: maximaal vermogen train je op frisse benen.", "ja": "スプリント10本と最初の30/30。きついセッションは週2回で十分：最大パワーはフレッシュな脚で鍛えます。", "tr": "10 sprint ve ilk 30/30''lar. Haftada iki zor antrenman yeterli: maksimum güç taze bacaklarla çalışılır."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Semaine de pic : 12 sprints, 10 relances et 3 séries de 30/30, une endurance TT au milieu. C''est la seule semaine du cycle à 3 séances dures.", "en": "Peak week: 12 sprints, 10 surges and 3 sets of 30/30, with a TT endurance ride in the middle. It''s the only week of the cycle with 3 hard sessions.", "es": "Semana pico: 12 sprints, 10 cambios de ritmo y 3 series de 30/30, con una resistencia en TT en medio. Es la única semana del ciclo con 3 sesiones duras.", "it": "Settimana di picco: 12 sprint, 10 rilanci e 3 serie di 30/30, un endurance in TT nel mezzo. È l''unica settimana del ciclo con 3 sedute dure.", "pt": "Semana de pico: 12 sprints, 10 retomadas e 3 séries de 30/30, com um endurance em TT no meio. É a única semana do ciclo com 3 sessões duras.", "de": "Spitzenwoche: 12 Sprints, 10 Antritte und 3 Serien 30/30, eine TT-Grundlageneinheit in der Mitte. Die einzige Woche des Zyklus mit 3 harten Einheiten.", "nl": "Piekweek: 12 sprints, 10 versnellingen en 3 series 30/30, met een duurtraining in TT ertussen. De enige week van de cyclus met 3 zware trainingen.", "ja": "ピーク週：スプリント12本、加速10本、30/30を3セット、真ん中にTTでのエンデュランス。サイクルで唯一きついセッションが3回ある週です。", "tr": "Zirve haftası: 12 sprint, 10 atak ve 3 set 30/30, ortada bir TT dayanıklılık. Döngünün 3 zor antrenmanlı tek haftası."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Allègement : moins de répétitions, une endurance TT de 40''. La fraîcheur revient et les sprints doivent sortir plus fort qu''en semaine 1.", "en": "Lighter week: fewer reps, a 40'' TT endurance ride. Freshness comes back and your sprints should come out stronger than in week 1.", "es": "Semana más ligera: menos repeticiones, una resistencia en TT de 40''. La frescura vuelve y los sprints deben salir más fuertes que en la semana 1.", "it": "Settimana di scarico: meno ripetute, un endurance in TT di 40''. La freschezza torna e gli sprint devono uscire più forti che in settimana 1.", "pt": "Semana mais leve: menos repetições, um endurance em TT de 40''. A disposição volta e os sprints devem sair mais fortes que na semana 1.", "de": "Entlastung: weniger Wiederholungen, 40'' TT-Grundlage. Die Frische kehrt zurück und die Sprints sollten stärker ausfallen als in Woche 1.", "nl": "Afbouw: minder herhalingen, 40'' duur in TT. De frisheid komt terug en de sprints moeten krachtiger zijn dan in week 1.", "ja": "軽めの週：反復を減らし、TTでのエンデュランス40''。フレッシュさが戻り、スプリントは1週目より強く出るはずです。", "tr": "Hafifletme: daha az tekrar, 40'' TT dayanıklılık. Tazelik geri geliyor ve sprintler 1. haftadakinden daha güçlü çıkmalı."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,5}', '{"fr": "Deuxième cycle : sprints de 20'''' à 175 % FTP et relances à 125 %, toujours séparés par une endurance TT et une sortie longue.", "en": "Second cycle: 20'''' sprints at 175 % FTP and surges at 125 %, still separated by a TT endurance ride and a long ride.", "es": "Segundo ciclo: sprints de 20'''' al 175 % FTP y cambios de ritmo al 125 %, siempre separados por una resistencia en TT y una salida larga.", "it": "Secondo ciclo: sprint di 20'''' al 175 % FTP e rilanci al 125 %, sempre separati da un endurance in TT e un''uscita lunga.", "pt": "Segundo ciclo: sprints de 20'''' a 175 % FTP e retomadas a 125 %, sempre separados por um endurance em TT e um treino longo.", "de": "Zweiter Zyklus: 20''''-Sprints bei 175 % FTP und Antritte bei 125 %, weiterhin getrennt durch eine TT-Grundlageneinheit und eine lange Fahrt.", "nl": "Tweede cyclus: sprints van 20'''' op 175 % FTP en versnellingen op 125 %, nog steeds gescheiden door een duurtraining in TT en een lange rit.", "ja": "第2サイクル：FTPの175 %で20''''のスプリント、125 %で加速。引き続きTTでのエンデュランスとロングライドを挟みます。", "tr": "İkinci döngü: FTP''nin %175''inde 20'''' sprintler ve %125''te ataklar, yine bir TT dayanıklılık ve bir uzun sürüşle ayrılmış."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,6}', '{"fr": "10 sprints de 20'''' et 3×10 30/30, une heure d''endurance TT entre les deux. Récupère complètement entre les sprints : un sprint lent n''entraîne pas la puissance max.", "en": "10 sprints of 20'''' and 3×10 30/30, with an hour of TT endurance in between. Recover fully between sprints: a slow sprint doesn''t train max power.", "es": "10 sprints de 20'''' y 3×10 30/30, con una hora de resistencia en TT entre ambos. Recupera por completo entre sprints: un sprint lento no entrena la potencia máxima.", "it": "10 sprint di 20'''' e 3×10 30/30, con un''ora di endurance in TT nel mezzo. Recupera completamente tra gli sprint: uno sprint lento non allena la potenza massima.", "pt": "10 sprints de 20'''' e 3×10 30/30, com uma hora de endurance em TT entre os dois. Recupere totalmente entre os sprints: um sprint lento não treina a potência máxima.", "de": "10 Sprints à 20'''' und 3×10 30/30, eine Stunde TT-Grundlage dazwischen. Erhol dich zwischen den Sprints vollständig: Ein langsamer Sprint trainiert keine Maximalleistung.", "nl": "10 sprints van 20'''' en 3×10 30/30, met een uur duur in TT ertussen. Herstel volledig tussen de sprints: een trage sprint traint geen maximaal vermogen.", "ja": "20''''のスプリント10本と3×10の30/30、間にTTでのエンデュランス1時間。スプリント間は完全に回復すること：遅いスプリントでは最大パワーは鍛えられません。", "tr": "10 adet 20'''' sprint ve 3×10 30/30, arada bir saat TT dayanıklılık. Sprintler arasında tamamen toparlan: yavaş bir sprint maksimum gücü geliştirmez."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,7}', '{"fr": "Pic du plan : 12 sprints à 180 %, 12 relances et 4 séries de 30/30, une heure d''endurance TT au milieu.", "en": "Plan peak: 12 sprints at 180 %, 12 surges and 4 sets of 30/30, with an hour of TT endurance in the middle.", "es": "Pico del plan: 12 sprints al 180 %, 12 cambios de ritmo y 4 series de 30/30, con una hora de resistencia en TT en medio.", "it": "Picco del piano: 12 sprint al 180 %, 12 rilanci e 4 serie di 30/30, con un''ora di endurance in TT nel mezzo.", "pt": "Pico do plano: 12 sprints a 180 %, 12 retomadas e 4 séries de 30/30, com uma hora de endurance em TT no meio.", "de": "Höhepunkt des Plans: 12 Sprints bei 180 %, 12 Antritte und 4 Serien 30/30, eine Stunde TT-Grundlage in der Mitte.", "nl": "Hoogtepunt van het plan: 12 sprints op 180 %, 12 versnellingen en 4 series 30/30, met een uur duur in TT ertussen.", "ja": "プランのピーク：180 %でスプリント12本、加速12本、30/30を4セット、真ん中にTTでのエンデュランス1時間。", "tr": "Planın zirvesi: %180''de 12 sprint, 12 atak ve 4 set 30/30, ortada bir saat TT dayanıklılık."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,8}', '{"fr": "Affûtage : volume minimal, intensité intacte. Tu termines frais, avec une puissance max en TT nettement au-dessus de celle de la semaine 1.", "en": "Taper: minimal volume, intensity intact. You finish fresh, with max power in TT well above week 1.", "es": "Puesta a punto: volumen mínimo, intensidad intacta. Terminas fresco, con una potencia máxima en TT muy por encima de la de la semana 1.", "it": "Scarico: volume minimo, intensità intatta. Finisci fresco, con una potenza massima in TT nettamente sopra quella della settimana 1.", "pt": "Polimento: volume mínimo, intensidade intacta. Você termina descansado, com uma potência máxima em TT bem acima da semana 1.", "de": "Tapering: minimaler Umfang, Intensität unverändert. Du beendest den Plan frisch, mit einer Maximalleistung in TT deutlich über der von Woche 1.", "nl": "Taperen: minimaal volume, intensiteit intact. Je eindigt fris, met een maximaal vermogen in TT duidelijk boven dat van week 1.", "ja": "調整（テーパー）：ボリュームは最小、強度はそのまま。フレッシュな状態で終え、TTでの最大パワーは1週目を明らかに上回ります。", "tr": "Yarış öncesi yük azaltma: minimum hacim, yoğunluk aynen. Taze bitiriyorsun, TT''deki maksimum gücün 1. haftanınkinin belirgin şekilde üstünde."}'::jsonb) WHERE name_key = 'sprint_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Découverte : sprints de 15'''' et relances d''1'' en TT, séparés par une endurance TT, plus une sortie longue. On apprend le geste explosif en position.", "en": "Discovery: 15'''' sprints and one-minute surges in TT, separated by a TT endurance ride, plus a long ride. You learn the explosive movement in position.", "es": "Descubrimiento: sprints de 15'''' y cambios de ritmo de 1'' en TT, separados por una resistencia en TT, más una salida larga. Aprendes el gesto explosivo en posición.", "it": "Scoperta: sprint di 15'''' e rilanci di 1'' in TT, separati da un endurance in TT, più un''uscita lunga. Impari il gesto esplosivo in posizione.", "pt": "Descoberta: sprints de 15'''' e retomadas de 1'' em TT, separados por um endurance em TT, mais um treino longo. Você aprende o gesto explosivo na posição.", "de": "Kennenlernen: 15''''-Sprints und Antritte à 1'' in TT, getrennt durch eine TT-Grundlageneinheit, dazu eine lange Fahrt. Du lernst die explosive Bewegung in Position.", "nl": "Kennismaking: sprints van 15'''' en versnellingen van 1'' in TT, gescheiden door een duurtraining in TT, plus een lange rit. Je leert de explosieve beweging in houding.", "ja": "導入：TTで15''''のスプリントと1''の加速、間にTTでのエンデュランス、さらにロングライド。ポジションを保ったまま爆発的な動きを学びます。", "tr": "Keşif: TT''de 15'''' sprintler ve 1'' ataklar, araya bir TT dayanıklılık, ayrıca bir uzun sürüş. Pozisyonda patlayıcı hareketi öğreniyorsun."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "10 sprints et les premiers 30/30. Deux séances dures par semaine suffisent : la puissance max se travaille sur des jambes fraîches.", "en": "10 sprints and the first 30/30s. Two hard sessions a week are enough: max power is trained on fresh legs.", "es": "10 sprints y los primeros 30/30. Dos sesiones duras por semana bastan: la potencia máxima se trabaja con piernas frescas.", "it": "10 sprint e i primi 30/30. Due sedute dure a settimana bastano: la potenza massima si allena su gambe fresche.", "pt": "10 sprints e os primeiros 30/30. Duas sessões duras por semana bastam: a potência máxima se treina com pernas descansadas.", "de": "10 Sprints und die ersten 30/30. Zwei harte Einheiten pro Woche reichen: Maximalleistung trainierst du auf frischen Beinen.", "nl": "10 sprints en de eerste 30/30''s. Twee zware trainingen per week volstaan: maximaal vermogen train je op frisse benen.", "ja": "スプリント10本と最初の30/30。きついセッションは週2回で十分：最大パワーはフレッシュな脚で鍛えます。", "tr": "10 sprint ve ilk 30/30''lar. Haftada iki zor antrenman yeterli: maksimum güç taze bacaklarla çalışılır."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Pic du premier cycle : 12 sprints, 10 relances et 3 séries de 30/30, une endurance TT au milieu.", "en": "First-cycle peak: 12 sprints, 10 surges and 3 sets of 30/30, with a TT endurance ride in the middle.", "es": "Pico del primer ciclo: 12 sprints, 10 cambios de ritmo y 3 series de 30/30, con una resistencia en TT en medio.", "it": "Picco del primo ciclo: 12 sprint, 10 rilanci e 3 serie di 30/30, un endurance in TT nel mezzo.", "pt": "Pico do primeiro ciclo: 12 sprints, 10 retomadas e 3 séries de 30/30, com um endurance em TT no meio.", "de": "Höhepunkt des ersten Zyklus: 12 Sprints, 10 Antritte und 3 Serien 30/30, eine TT-Grundlageneinheit in der Mitte.", "nl": "Hoogtepunt van de eerste cyclus: 12 sprints, 10 versnellingen en 3 series 30/30, met een duurtraining in TT ertussen.", "ja": "第1サイクルのピーク：スプリント12本、加速10本、30/30を3セット、真ん中にTTでのエンデュランス。", "tr": "İlk döngünün zirvesi: 12 sprint, 10 atak ve 3 set 30/30, ortada bir TT dayanıklılık."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Allègement : moins de répétitions, une endurance TT. Les sprints doivent sortir plus fort qu''en semaine 1.", "en": "Lighter week: fewer reps, one TT endurance ride. Your sprints should come out stronger than in week 1.", "es": "Semana más ligera: menos repeticiones, una resistencia en TT. Los sprints deben salir más fuertes que en la semana 1.", "it": "Settimana di scarico: meno ripetute, un endurance in TT. Gli sprint devono uscire più forti che in settimana 1.", "pt": "Semana mais leve: menos repetições, um endurance em TT. Os sprints devem sair mais fortes que na semana 1.", "de": "Entlastung: weniger Wiederholungen, eine TT-Grundlageneinheit. Die Sprints sollten stärker ausfallen als in Woche 1.", "nl": "Afbouw: minder herhalingen, één duurtraining in TT. De sprints moeten krachtiger zijn dan in week 1.", "ja": "軽めの週：反復を減らし、TTでのエンデュランス。スプリントは1週目より強く出るはずです。", "tr": "Hafifletme: daha az tekrar, bir TT dayanıklılık. Sprintler 1. haftadakinden daha güçlü çıkmalı."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,5}', '{"fr": "Deuxième cycle : sprints de 20'''' à 175 % et relances à 125 %, séparés par une endurance TT et une sortie longue.", "en": "Second cycle: 20'''' sprints at 175 % and surges at 125 %, separated by a TT endurance ride and a long ride.", "es": "Segundo ciclo: sprints de 20'''' al 175 % y cambios de ritmo al 125 %, separados por una resistencia en TT y una salida larga.", "it": "Secondo ciclo: sprint di 20'''' al 175 % e rilanci al 125 %, separati da un endurance in TT e un''uscita lunga.", "pt": "Segundo ciclo: sprints de 20'''' a 175 % e retomadas a 125 %, separados por um endurance em TT e um treino longo.", "de": "Zweiter Zyklus: 20''''-Sprints bei 175 % und Antritte bei 125 %, getrennt durch eine TT-Grundlageneinheit und eine lange Fahrt.", "nl": "Tweede cyclus: sprints van 20'''' op 175 % en versnellingen op 125 %, gescheiden door een duurtraining in TT en een lange rit.", "ja": "第2サイクル：175 %で20''''のスプリント、125 %で加速。間にTTでのエンデュランスとロングライドを挟みます。", "tr": "İkinci döngü: %175''te 20'''' sprintler ve %125''te ataklar, bir TT dayanıklılık ve bir uzun sürüşle ayrılmış."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,6}', '{"fr": "10 sprints de 20'''' et 3×10 30/30, une heure d''endurance TT entre les deux. Récupère complètement entre les sprints.", "en": "10 sprints of 20'''' and 3×10 30/30, with an hour of TT endurance in between. Recover fully between sprints.", "es": "10 sprints de 20'''' y 3×10 30/30, con una hora de resistencia en TT entre ambos. Recupera por completo entre sprints.", "it": "10 sprint di 20'''' e 3×10 30/30, con un''ora di endurance in TT nel mezzo. Recupera completamente tra gli sprint.", "pt": "10 sprints de 20'''' e 3×10 30/30, com uma hora de endurance em TT entre os dois. Recupere totalmente entre os sprints.", "de": "10 Sprints à 20'''' und 3×10 30/30, eine Stunde TT-Grundlage dazwischen. Erhol dich zwischen den Sprints vollständig.", "nl": "10 sprints van 20'''' en 3×10 30/30, met een uur duur in TT ertussen. Herstel volledig tussen de sprints.", "ja": "20''''のスプリント10本と3×10の30/30、間にTTでのエンデュランス1時間。スプリント間は完全に回復すること。", "tr": "10 adet 20'''' sprint ve 3×10 30/30, arada bir saat TT dayanıklılık. Sprintler arasında tamamen toparlan."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,7}', '{"fr": "Pic du deuxième cycle : 12 sprints à 180 %, 12 relances et 4 séries de 30/30.", "en": "Second-cycle peak: 12 sprints at 180 %, 12 surges and 4 sets of 30/30.", "es": "Pico del segundo ciclo: 12 sprints al 180 %, 12 cambios de ritmo y 4 series de 30/30.", "it": "Picco del secondo ciclo: 12 sprint al 180 %, 12 rilanci e 4 serie di 30/30.", "pt": "Pico do segundo ciclo: 12 sprints a 180 %, 12 retomadas e 4 séries de 30/30.", "de": "Höhepunkt des zweiten Zyklus: 12 Sprints bei 180 %, 12 Antritte und 4 Serien 30/30.", "nl": "Hoogtepunt van de tweede cyclus: 12 sprints op 180 %, 12 versnellingen en 4 series 30/30.", "ja": "第2サイクルのピーク：180 %でスプリント12本、加速12本、30/30を4セット。", "tr": "İkinci döngünün zirvesi: %180''de 12 sprint, 12 atak ve 4 set 30/30."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,8}', '{"fr": "Allègement avant le dernier cycle. La fraîcheur fait ressortir le gain des huit premières semaines.", "en": "Lighter week before the final cycle. Freshness brings out the gains of the first eight weeks.", "es": "Semana más ligera antes del último ciclo. La frescura hace aflorar lo ganado en las ocho primeras semanas.", "it": "Settimana di scarico prima dell''ultimo ciclo. La freschezza fa emergere il guadagno delle prime otto settimane.", "pt": "Semana mais leve antes do último ciclo. A disposição faz aparecer o ganho das oito primeiras semanas.", "de": "Entlastung vor dem letzten Zyklus. Die Frische bringt den Gewinn der ersten acht Wochen zum Vorschein.", "nl": "Afbouw voor de laatste cyclus. De frisheid laat de winst van de eerste acht weken zien.", "ja": "最終サイクル前の軽めの週。フレッシュさが最初の8週間の成果を引き出します。", "tr": "Son döngüden önce hafifletme. Tazelik ilk sekiz haftanın kazancını ortaya çıkarır."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,9}', '{"fr": "Troisième cycle : 12 sprints et 4×10 30/30, une heure d''endurance TT et une sortie longue en TT.", "en": "Third cycle: 12 sprints and 4×10 30/30, an hour of TT endurance and a long ride in TT.", "es": "Tercer ciclo: 12 sprints y 4×10 30/30, una hora de resistencia en TT y una salida larga en TT.", "it": "Terzo ciclo: 12 sprint e 4×10 30/30, un''ora di endurance in TT e un''uscita lunga in TT.", "pt": "Terceiro ciclo: 12 sprints e 4×10 30/30, uma hora de endurance em TT e um treino longo em TT.", "de": "Dritter Zyklus: 12 Sprints und 4×10 30/30, eine Stunde TT-Grundlage und eine lange Fahrt in TT.", "nl": "Derde cyclus: 12 sprints en 4×10 30/30, een uur duur in TT en een lange rit in TT.", "ja": "第3サイクル：スプリント12本と4×10の30/30、TTでのエンデュランス1時間とTTでのロングライド。", "tr": "Üçüncü döngü: 12 sprint ve 4×10 30/30, bir saat TT dayanıklılık ve TT''de bir uzun sürüş."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,10}', '{"fr": "14 sprints et 14 relances, 70'' d''endurance TT : le volume d''efforts explosifs monte, toujours deux séances dures seulement.", "en": "14 sprints and 14 surges, 70'' of TT endurance: the volume of explosive efforts rises, still with only two hard sessions.", "es": "14 sprints y 14 cambios de ritmo, 70'' de resistencia en TT: el volumen de esfuerzos explosivos sube, siempre con solo dos sesiones duras.", "it": "14 sprint e 14 rilanci, 70'' di endurance in TT: il volume di sforzi esplosivi sale, sempre con due sole sedute dure.", "pt": "14 sprints e 14 retomadas, 70'' de endurance em TT: o volume de esforços explosivos sobe, sempre com só duas sessões duras.", "de": "14 Sprints und 14 Antritte, 70'' TT-Grundlage: Der Umfang an explosiven Belastungen steigt, weiterhin nur zwei harte Einheiten.", "nl": "14 sprints en 14 versnellingen, 70'' duur in TT: het volume explosieve inspanningen stijgt, nog steeds maar twee zware trainingen.", "ja": "スプリント14本と加速14本、TTでのエンデュランス70''：爆発的な努力のボリュームが増えますが、きついセッションは引き続き2回だけです。", "tr": "14 sprint ve 14 atak, 70'' TT dayanıklılık: patlayıcı efor hacmi artıyor, yine sadece iki zor antrenman."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,11}', '{"fr": "Pic du plan : 14 sprints, 14 relances et 5 séries de 30/30, 75'' d''endurance TT au milieu. La semaine la plus exigeante du programme.", "en": "Plan peak: 14 sprints, 14 surges and 5 sets of 30/30, with 75'' of TT endurance in the middle. The most demanding week of the program.", "es": "Pico del plan: 14 sprints, 14 cambios de ritmo y 5 series de 30/30, con 75'' de resistencia en TT en medio. La semana más exigente del programa.", "it": "Picco del piano: 14 sprint, 14 rilanci e 5 serie di 30/30, con 75'' di endurance in TT nel mezzo. La settimana più impegnativa del programma.", "pt": "Pico do plano: 14 sprints, 14 retomadas e 5 séries de 30/30, com 75'' de endurance em TT no meio. A semana mais exigente do programa.", "de": "Höhepunkt des Plans: 14 Sprints, 14 Antritte und 5 Serien 30/30, 75'' TT-Grundlage in der Mitte. Die anspruchsvollste Woche des Programms.", "nl": "Hoogtepunt van het plan: 14 sprints, 14 versnellingen en 5 series 30/30, met 75'' duur in TT ertussen. De zwaarste week van het programma.", "ja": "プランのピーク：スプリント14本、加速14本、30/30を5セット、真ん中にTTでのエンデュランス75''。プログラムで最も厳しい週です。", "tr": "Planın zirvesi: 14 sprint, 14 atak ve 5 set 30/30, ortada 75'' TT dayanıklılık. Programın en zorlu haftası."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,12}', '{"fr": "Affûtage : volume minimal, intensité intacte. Ta puissance max en TT doit être au plus haut.", "en": "Taper: minimal volume, intensity intact. Your max power in TT should be at its highest.", "es": "Puesta a punto: volumen mínimo, intensidad intacta. Tu potencia máxima en TT debe estar en su punto más alto.", "it": "Scarico: volume minimo, intensità intatta. La tua potenza massima in TT deve essere al massimo.", "pt": "Polimento: volume mínimo, intensidade intacta. Sua potência máxima em TT deve estar no ponto mais alto.", "de": "Tapering: minimaler Umfang, Intensität unverändert. Deine Maximalleistung in TT sollte auf dem Höchststand sein.", "nl": "Taperen: minimaal volume, intensiteit intact. Je maximale vermogen in TT moet op zijn hoogst zijn.", "ja": "調整（テーパー）：ボリュームは最小、強度はそのまま。TTでの最大パワーが最高に達しているはずです。", "tr": "Yarış öncesi yük azaltma: minimum hacim, yoğunluk aynen. TT''deki maksimum gücün en üst seviyede olmalı."}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,1}', '{"fr": "Mise en route : sweet spot 3×12'' et seuil 4×8'' en TT, une endurance TT entre les deux et une sortie longue. On établit ce que tu produis couché.", "en": "Getting started: sweet spot 3×12'' and threshold 4×8'' in TT, with a TT endurance ride in between and a long ride. We establish what you produce tucked low.", "es": "Puesta en marcha: sweet spot 3×12'' y umbral 4×8'' en TT, con una resistencia en TT entre ambos y una salida larga. Establecemos lo que produces acoplado.", "it": "Avvio: sweet spot 3×12'' e soglia 4×8'' in TT, un endurance in TT nel mezzo e un''uscita lunga. Stabiliamo ciò che produci in posizione aero.", "pt": "Início: sweet spot 3×12'' e limiar 4×8'' em TT, com um endurance em TT entre os dois e um treino longo. Estabelecemos o que você produz em posição aero.", "de": "Einstieg: Sweet Spot 3×12'' und Schwelle 4×8'' in TT, eine TT-Grundlageneinheit dazwischen und eine lange Fahrt. Wir ermitteln, was du liegend leistest.", "nl": "Instap: sweet spot 3×12'' en drempel 4×8'' in TT, met een duurtraining in TT ertussen en een lange rit. We bepalen wat je liggend levert.", "ja": "導入：TTでスイートスポット3×12''と閾値4×8''、間にTTでのエンデュランス、さらにロングライド。伏せた姿勢で出せるパワーを把握します。", "tr": "Başlangıç: TT''de sweet spot 3×12'' ve eşik 4×8'', arada bir TT dayanıklılık ve bir uzun sürüş. Yatık pozisyonda ne ürettiğini belirliyoruz."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,2}', '{"fr": "Sweet spot 3×15'' et premiers sur-sous, séparés par du tempo en TT. Changer d''intensité sans bouger de position, comme sur un parcours vallonné.", "en": "Sweet spot 3×15'' and first over-unders, separated by tempo in TT. Changing intensity without moving out of position, like on a rolling course.", "es": "Sweet spot 3×15'' y primeros sobre-bajo, separados por tempo en TT. Cambiar de intensidad sin moverte de la posición, como en un recorrido ondulado.", "it": "Sweet spot 3×15'' e primi sopra-sotto, separati da ritmo tempo in TT. Cambiare intensità senza muoversi dalla posizione, come su un percorso ondulato.", "pt": "Sweet spot 3×15'' e primeiros acima-abaixo, separados por ritmo tempo em TT. Mudar de intensidade sem sair da posição, como num percurso ondulado.", "de": "Sweet Spot 3×15'' und erste Over-Under, getrennt durch Tempo in TT. Die Intensität wechseln, ohne die Position zu verändern, wie auf einer welligen Strecke.", "nl": "Sweet spot 3×15'' en eerste over-unders, gescheiden door tempo in TT. Van intensiteit wisselen zonder je houding te veranderen, zoals op een heuvelachtig parcours.", "ja": "スイートスポット3×15''と最初のオーバーアンダー、間にTTでのテンポ。起伏のあるコースのように、ポジションを動かさずに強度を変えます。", "tr": "Sweet spot 3×15'' ve ilk üst-altlar, araya TT''de tempo. İnişli çıkışlı bir parkurdaki gibi, pozisyonu bozmadan yoğunluk değiştirmek."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,3}', '{"fr": "Semaine de pic : 3×12'' au seuil, sur-sous et 5×4'' à la puissance critique. Seule semaine du cycle à 3 séances dures ; le tempo au milieu reste facile.", "en": "Peak week: 3×12'' at threshold, over-unders and 5×4'' at critical power. The only week of the cycle with 3 hard sessions; the tempo in the middle stays easy.", "es": "Semana pico: 3×12'' al umbral, sobre-bajo y 5×4'' a potencia crítica. Única semana del ciclo con 3 sesiones duras; el tempo en medio sigue siendo fácil.", "it": "Settimana di picco: 3×12'' in soglia, sopra-sotto e 5×4'' alla potenza critica. Unica settimana del ciclo con 3 sedute dure; il ritmo tempo nel mezzo resta facile.", "pt": "Semana de pico: 3×12'' no limiar, acima-abaixo e 5×4'' na potência crítica. Única semana do ciclo com 3 sessões duras; o ritmo tempo no meio continua fácil.", "de": "Spitzenwoche: 3×12'' an der Schwelle, Over-Under und 5×4'' bei kritischer Leistung. Die einzige Woche des Zyklus mit 3 harten Einheiten; das Tempo in der Mitte bleibt locker.", "nl": "Piekweek: 3×12'' op drempel, over-unders en 5×4'' op kritisch vermogen. De enige week van de cyclus met 3 zware trainingen; het tempo ertussen blijft makkelijk.", "ja": "ピーク週：閾値3×12''、オーバーアンダー、クリティカルパワー5×4''。サイクルで唯一きついセッションが3回ある週で、真ん中のテンポは楽に保ちます。", "tr": "Zirve haftası: eşikte 3×12'', üst-altlar ve kritik güçte 5×4''. Döngünün 3 zor antrenmanlı tek haftası; ortadaki tempo kolay kalır."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,4}', '{"fr": "Allègement : volume divisé par deux, intensité conservée sur des blocs courts. C''est pendant cette semaine que la FTP monte réellement.", "en": "Lighter week: volume halved, intensity kept on short blocks. This is the week your FTP actually rises.", "es": "Semana más ligera: volumen a la mitad, intensidad mantenida en bloques cortos. Es durante esta semana cuando la FTP sube de verdad.", "it": "Settimana di scarico: volume dimezzato, intensità mantenuta su blocchi brevi. È in questa settimana che la FTP sale davvero.", "pt": "Semana mais leve: volume pela metade, intensidade mantida em blocos curtos. É nesta semana que a FTP sobe de verdade.", "de": "Entlastung: Umfang halbiert, Intensität auf kurzen Blöcken beibehalten. In dieser Woche steigt die FTP tatsächlich.", "nl": "Afbouw: volume gehalveerd, intensiteit behouden op korte blokken. Tijdens deze week stijgt de FTP echt.", "ja": "軽めの週：ボリュームは半分、短いブロックで強度は維持。FTPが実際に上がるのはこの週です。", "tr": "Hafifletme: hacim yarıya iniyor, kısa bloklarda yoğunluk korunuyor. FTP''nin gerçekten yükseldiği hafta bu."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,5}', '{"fr": "Deuxième cycle : 3×20'' en sweet spot et 3×15'' au seuil, des blocs proches d''un CLM. Le tempo et la sortie longue tiennent la position sans fatigue.", "en": "Second cycle: 3×20'' at sweet spot and 3×15'' at threshold, blocks close to a TT. Tempo and the long ride hold your position without fatigue.", "es": "Segundo ciclo: 3×20'' en sweet spot y 3×15'' al umbral, bloques cercanos a una CRI. El tempo y la salida larga mantienen la posición sin fatiga.", "it": "Secondo ciclo: 3×20'' in sweet spot e 3×15'' in soglia, blocchi vicini a una crono. Il ritmo tempo e l''uscita lunga mantengono la posizione senza fatica.", "pt": "Segundo ciclo: 3×20'' em sweet spot e 3×15'' no limiar, blocos próximos de um contrarrelógio. O ritmo tempo e o treino longo sustentam a posição sem cansaço.", "de": "Zweiter Zyklus: 3×20'' im Sweet Spot und 3×15'' an der Schwelle, Blöcke nahe an einem Zeitfahren. Tempo und lange Fahrt halten die Position ohne Ermüdung.", "nl": "Tweede cyclus: 3×20'' in sweet spot en 3×15'' op drempel, blokken dicht bij een tijdrit. Het tempo en de lange rit houden de houding vast zonder vermoeidheid.", "ja": "第2サイクル：スイートスポット3×20''と閾値3×15''、タイムトライアルに近いブロック。テンポとロングライドで疲労なしにポジションを保ちます。", "tr": "İkinci döngü: sweet spot''ta 3×20'' ve eşikte 3×15'', bir zamana karşıya yakın bloklar. Tempo ve uzun sürüş pozisyonu yorgunluk olmadan korur."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,6}', '{"fr": "2×30'' en sweet spot et 4 séries de sur-sous : les efforts longs en TT font le plus progresser la FTP en aéro.", "en": "2×30'' at sweet spot and 4 sets of over-unders: long efforts in TT do the most to raise your aero FTP.", "es": "2×30'' en sweet spot y 4 series de sobre-bajo: los esfuerzos largos en TT son los que más hacen progresar la FTP en aero.", "it": "2×30'' in sweet spot e 4 serie di sopra-sotto: gli sforzi lunghi in TT sono quelli che fanno progredire di più la FTP in aero.", "pt": "2×30'' em sweet spot e 4 séries de acima-abaixo: os esforços longos em TT são os que mais fazem a FTP em aero progredir.", "de": "2×30'' im Sweet Spot und 4 Serien Over-Under: Lange Belastungen in TT bringen die FTP in Aero-Position am weitesten voran.", "nl": "2×30'' in sweet spot en 4 series over-unders: lange inspanningen in TT laten de FTP in aerohouding het meest vooruitgaan.", "ja": "スイートスポット2×30''とオーバーアンダー4セット：TTでの長い努力こそ、エアロでのFTPを最も伸ばします。", "tr": "Sweet spot''ta 2×30'' ve 4 set üst-alt: TT''deki uzun eforlar aero''daki FTP''yi en çok geliştirir."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(translations_json, '{weeks,7}', '{"fr": "Pic du plan : 3×20'' au seuil, 4×10 sur-sous et 6×5'' à 108 %. Tout ce que tu tiens ici sera acquis.", "en": "Plan peak: 3×20'' at threshold, 4×10 over-unders and 6×5'' at 108 %. Whatever you hold here is yours to keep.", "es": "Pico del plan: 3×20'' al umbral, 4×10 sobre-bajo y 6×5'' al 108 %. Todo lo que aguantes aquí quedará adquirido.", "it": "Picco del piano: 3×20'' in soglia, 4×10 sopra-sotto e 6×5'' al 108 %. Tutto ciò che tieni qui sarà acquisito.", "pt": "Pico do plano: 3×20'' no limiar, 4×10 acima-abaixo e 6×5'' a 108 %. Tudo o que você segurar aqui ficará conquistado.", "de": "Höhepunkt des Plans: 3×20'' an der Schwelle, 4×10 Over-Under und 6×5'' bei 108 %. Alles, was du hier hältst, sitzt.", "nl": "Hoogtepunt van het plan: 3×20'' op drempel, 4×10 over-unders en 6×5'' op 108 %. Alles wat je hier volhoudt, is verworven.", "ja": "プランのピーク：閾値3×20''、オーバーアンダー4×10、108 %で6×5''。ここで保てたものはすべて身につきます。", "tr": "Planın zirvesi: eşikte 3×20'', 4×10 üst-alt ve %108''de 6×5''. Burada tuttuğun her şey kalıcı olacak."}'::jsonb) WHERE name_key = 'threshold_tt_8w_name';
